use serde_json::json;
#[test]
fn repl_offers_exact_file_schemas_and_persists_audit(){let d=tempfile::tempdir().unwrap();let log=tempfile::tempdir().unwrap();let config=d.path().join("rig.toml");std::fs::write(&config,format!("[[models]]\nname='seqmodel'\ncommand=['{}']\ndefault=true\n",env!("CARGO_BIN_EXE_hs-plugin-seqmodel"))).unwrap();let s=hs_loop::repl::ReplSession::load(&config,log.path(),false,Some(2)).unwrap();let audit:serde_json::Value=serde_json::from_str(&std::fs::read_to_string(log.path().join("tools.json")).unwrap()).unwrap();for name in ["read","write","edit"]{assert!(s.native_tool_names().contains(&name.to_string()));let expected=hs_loop::dshtools::schema(name).unwrap();let actual=audit.as_array().unwrap().iter().find(|t|t["function"]["name"]==name).unwrap();assert_eq!(actual["function"]["description"],expected["description"]);assert_eq!(actual["function"]["parameters"],expected["input_schema"]);}}
#[test]
fn read_and_edits_keep_checker_ledger_grounded(){let mut ledger=hs_loop::ledger::Ledger::default();ledger.apply_tool_call(1,"read",&json!({"file_path":"a","offset":2,"limit":1}),&json!({"lines":[{"number":2,"text":"important evidence"}],"total_lines":3}));let text=ledger.summary();assert!(text.contains("important evidence"),"{text}");assert!(text.contains("a:L2-2"),"{text}");ledger.apply_tool_call(2,"edit",&json!({"file_path":"a"}),&json!({"path":"a","before":"one","after":"two"}));assert!(ledger.summary().contains("a"));}
